class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        length = n + m - 1

        res = [None] * length
        forced = [False] * length

        # Apply all 'T' constraints
        for i in range(n):
            if str1[i] == 'T':
                for j in range(m):
                    pos = i + j
                    if res[pos] is not None and res[pos] != str2[j]:
                        return ""
                    res[pos] = str2[j]
                    forced[pos] = True

        # Fill unforced positions with 'a'
        for i in range(length):
            if res[i] is None:
                res[i] = 'a'

        # Check and fix 'F' constraints
        for i in range(n):
            if str1[i] == 'F':
                # Check if the window equals str2
                if all(res[i + k] == str2[k] for k in range(m)):
                    # Find the rightmost non-forced character in the window
                    j = i + m - 1
                    while j >= i and forced[j]:
                        j -= 1
                    if j < i:
                        return ""
                    # Change res[j] to the smallest character not equal to str2[j-i]
                    c = 'a'
                    while c == str2[j - i]:
                        c = chr(ord(c) + 1)
                    res[j] = c

        return "".join(res)

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        # Sort points to help with pruning in backtracking
        # Sorting by x then y is a simple heuristic
        points_sorted = sorted(points)
        n_sorted = len(points_sorted)

        # Precompute Manhattan distance matrix for sorted points
        dist_sorted = [[0] * n_sorted for _ in range(n_sorted)]
        for i in range(n_sorted):
            for j in range(i + 1, n_sorted):
                d = abs(points_sorted[i][0] - points_sorted[j][0]) + abs(points_sorted[i][1] - points_sorted[j][1])
                dist_sorted[i][j] = d
                dist_sorted[j][i] = d

        # Backtracking function to check if we can select k points with min distance >= d
        def can_select(d: int) -> bool:
            # selected: list of indices in points_sorted that are selected
            selected = []

            # Recursive function with pruning
            def backtrack(start_idx: int) -> bool:
                if len(selected) == k:
                    return True

                # Pruning: if remaining points are not enough
                if n_sorted - start_idx < k - len(selected):
                    return False

                # Try to pick the next point from start_idx onwards
                for i in range(start_idx, n_sorted):
                    # Check if point i is at least distance d from all selected points
                    valid = True
                    for s in selected:
                        if dist_sorted[i][s] < d:
                            valid = False
                            break
                    if valid:
                        selected.append(i)
                        if backtrack(i + 1):
                            return True
                        selected.pop()

                return False

            return backtrack(0)

        # Binary search for the maximum minimum distance
        low = 0
        high = 4 * side  # Maximum possible Manhattan distance on boundary
        ans = 0

        while low <= high:
            mid = (low + high) // 2
            if can_select(mid):
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        # Directions: NE, SE, SW, NW
        # NE: (-1, 1), SE: (1, 1), SW: (1, -1), NW: (-1, -1)
        dirs = [(-1, 1), (1, 1), (1, -1), (-1, -1)]
        dir_names = ['NE', 'SE', 'SW', 'NW']

        # Precompute dp2[r][c][d]: length of longest sequence starting at (r,c) in direction d
        # that matches 2,0,2,0,... (i.e., grid[r][c] must be 2, then 0, etc.)
        # Precompute dp0[r][c][d]: length of longest sequence starting at (r,c) in direction d
        # that matches 0,2,0,2,... (i.e., grid[r][c] must be 0, then 2, etc.)

        dp2 = [[[0]*4 for _ in range(m)] for _ in range(n)]
        dp0 = [[[0]*4 for _ in range(m)] for _ in range(n)]

        # We fill DP tables in reverse order of traversal for each direction.
        # For direction d, we iterate from the end of the grid in that direction backwards.

        for d in range(4):
            dr, dc = dirs[d]
            # Determine iteration order: 
            # If dr > 0, iterate rows from n-1 down to 0; if dr < 0, iterate rows from 0 to n-1.
            # Similarly for dc.
            if dr > 0:
                row_order = range(n-1, -1, -1)
            else:
                row_order = range(n)
            if dc > 0:
                col_order = range(m-1, -1, -1)
            else:
                col_order = range(m)

            for r in row_order:
                for c in col_order:
                    # For dp2: current must be 2, next must be 0, then 2, etc.
                    if grid[r][c] == 2:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            # Next should be 0, so we look at dp0[nr][nc][d]
                            dp2[r][c][d] = 1 + dp0[nr][nc][d]
                        else:
                            dp2[r][c][d] = 1
                    else:
                        dp2[r][c][d] = 0

                    # For dp0: current must be 0, next must be 2, then 0, etc.
                    if grid[r][c] == 0:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < n and 0 <= nc < m:
                            # Next should be 2, so we look at dp2[nr][nc][d]
                            dp0[r][c][d] = 1 + dp2[nr][nc][d]
                        else:
                            dp0[r][c][d] = 1
                    else:
                        dp0[r][c][d] = 0

        # Clockwise turns: 
        # NE -> SE, SE -> SW, SW -> NW, NW -> NE
        # Index mapping: 0:NE, 1:SE, 2:SW, 3:NW
        # Clockwise: 0->1, 1->2, 2->3, 3->0
        clockwise_turns = {0: 1, 1: 2, 2: 3, 3: 0}

        max_len = 0

        # For each cell that is 1, try all 4 starting directions
        for r in range(n):
            for c in range(m):
                if grid[r][c] != 1:
                    continue

                for d1 in range(4):
                    dr1, dc1 = dirs[d1]
                    # Extend in direction d1 as long as the sequence 1,2,0,2,0,... holds
                    # Start at (r,c) with value 1 (index 0)
                    # Next should be 2 (index 1), then 0 (index 2), etc.

                    # We can simulate the extension
                    cur_r, cur_c = r, c
                    length = 1  # includes the starting 1

                    # The next expected value after index i (0-indexed) is:
                    # i=0 (value 1) -> next is 2
                    # i=1 (value 2) -> next is 0
                    # i=2 (value 0) -> next is 2
                    # i=3 (value 2) -> next is 0
                    # So for i>=1: if i is odd -> 2, if i is even -> 0

                    # Extend as far as possible
                    while True:
                        # Current index in sequence is length-1
                        idx = length - 1
                        # Expected next value
                        if idx == 0:
                            expected = 2
                        else:
                            if idx % 2 == 1:
                                expected = 0
                            else:
                                expected = 2

                        nr, nc = cur_r + dr1, cur_c + dc1
                        if 0 <= nr < n and 0 <= nc < m and grid[nr][nc] == expected:
                            length += 1
                            cur_r, cur_c = nr, nc
                        else:
                            break

                    # Now, the segment ends at (cur_r, cur_c) with length 'length'
                    # The last value in the sequence is at index 'length-1'
                    # Determine what value is expected next for a continuation (for the turn)
                    idx_last = length - 1
                    if idx_last == 0:
                        expected_next = 2
                    else:
                        if idx_last % 2 == 1:
                            expected_next = 0
                        else:
                            expected_next = 2

                    # Update max_len with the straight segment (no turn)
                    if length > max_len:
                        max_len = length

                    # Try all clockwise turns from d1
                    d2 = clockwise_turns[d1]
                    dr2, dc2 = dirs[d2]

                    # Check the next cell in direction d2 from (cur_r, cur_c)
                    nr2, nc2 = cur_r + dr2, cur_c + dc2
                    if 0 <= nr2 < n and 0 <= nc2 < m:
                        if grid[nr2][nc2] == expected_next:
                            # Add the length of the chain starting from (nr2, nc2) in direction d2
                            if expected_next == 2:
                                suffix_len = dp2[nr2][nc2][d2]
                            else:
                                suffix_len = dp0[nr2][nc2][d2]

                            total_len = length + suffix_len
                            if total_len > max_len:
                                max_len = total_len

        return max_len

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0

        # d = 1, 2, 5: All substrings ending in d are divisible by d
        for d in [1, 2, 5]:
            for j in range(n):
                if int(s[j]) == d:
                    ans += j + 1

        # d = 4: Divisible by 4 iff last two digits form a number divisible by 4
        for j in range(n):
            if int(s[j]) == 4:
                if j == 0:
                    ans += 1
                else:
                    val = int(s[j-1:j+1])
                    if val % 4 == 0:
                        ans += j + 1
                    else:
                        ans += 1

        # d = 8: Divisible by 8 iff last three digits form a number divisible by 8
        for j in range(n):
            if int(s[j]) == 8:
                if j == 0:
                    ans += 1
                elif j == 1:
                    val = int(s[0:2])
                    if val % 8 == 0:
                        ans += 2
                    else:
                        ans += 1
                else:
                    val = int(s[j-2:j+1])
                    if val % 8 == 0:
                        ans += j + 1
                    else:
                        ans += 1

        # d = 3, 6, 9: Divisible by d iff sum of digits is divisible by d
        # For d=6, since it ends in 6, it's always even, so just check sum % 3 == 0
        for d in [3, 6, 9]:
            freq = [0] * d
            # prefix_sum[0] = 0
            freq[0] = 1
            current_sum = 0
            for j in range(n):
                current_sum += int(s[j])
                rem = current_sum % d
                if int(s[j]) == d:
                    # We need prefix_sum[i] % d == current_sum % d for i from 0 to j
                    ans += freq[rem]
                # Update freq for next iteration
                freq[rem] += 1

        # d = 7: Use frequency array with modular inverse
        # Precompute modular inverse of 10^k mod 7 for k=0..5
        # 10^0=1, 10^1=3, 10^2=2, 10^3=6, 10^4=4, 10^5=5
        # Inverses: inv(1)=1, inv(3)=5, inv(2)=4, inv(6)=6, inv(4)=2, inv(5)=3
        inv_pow = [1, 5, 4, 6, 2, 3]

        freq7 = [[0]*6 for _ in range(7)] # freq7[rem][index%6]
        # Initialize with prefix_sum[0] = 0 at index 0
        freq7[0][0] = 1

        current_rem = 0
        for j in range(n):
            digit = int(s[j])
            current_rem = (current_rem * 10 + digit) % 7
            idx = j + 1 # This is the index in the prefix array for the current position
            idx_mod = idx % 6

            if digit == 7:
                # We need to count i (0 <= i <= j) such that
                # P[i] * 10^(j-i+1) == P[j+1] (mod 7)
                # P[i] == P[j+1] * inv(10^(j-i+1)) (mod 7)
                # Let L = j-i+1. Then i = j+1-L.
                # i % 6 = (j+1-L) % 6 = (idx - L) % 6.
                # For a bucket `b = i % 6`, we have L % 6 = (idx - b) % 6.
                # Required P[i] = current_rem * inv_pow[(idx - b) % 6] % 7.

                for b in range(6):
                    req_rem = (current_rem * inv_pow[(idx - b) % 6]) % 7
                    ans += freq7[req_rem][b]

            # Update frequency array
            freq7[current_rem][idx_mod] += 1

        return ans

